import java.util.*;

public class Main {
    static final int MAXN = 210;
    static final int MAXM = 1000007;

    static int n, T;
    static String[] s1 = new String[15];
    static String[] s2 = new String[15];
    static int[][] id = new int[15][15];
    static int cnt;
    static int source, sink;
    static int xz, yz;
    static int[][] directions = { {0,1}, {0,-1}, {1,0}, {-1,0} };

    static int[] vv = new int[MAXM];
    static int[] cap = new int[MAXM];
    static int[] nxt = new int[MAXM];
    static int[] head = new int[MAXN];
    static int edge_idx = 0;
    static int[] parent = new int[MAXN];
    static int[] visited = new int[MAXN];

    static boolean check_inside(int x, int y) {
        return x >= 0 && y >= 0 && x < n && y < n && s1[x].charAt(y) >= '0' && s1[x].charAt(y) <= '9';
    }

    static void add_edge(int u, int v, int c) {
        vv[edge_idx] = v; cap[edge_idx] = c; nxt[edge_idx] = head[u]; head[u] = edge_idx++;
        vv[edge_idx] = u; cap[edge_idx] = 0; nxt[edge_idx] = head[v]; head[v] = edge_idx++;
    }

    static int run_max_flow() {
        int total = 0;
        while (true) {
            Arrays.fill(parent, -1);
            Arrays.fill(visited, 0);
            Queue<Integer> q = new LinkedList<>();
            q.offer(source);
            visited[source] = 1;
            boolean foundAugmentingPath = false;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int i = head[u]; i != -1; i = nxt[i]) {
                    int v = vv[i];
                    if (cap[i] > 0 && visited[v] == 0) {
                        visited[v] = 1;
                        parent[v] = i;
                        if (v == sink) {
                            foundAugmentingPath = true;
                            break;
                        }
                        q.offer(v);
                    }
                }
                if (foundAugmentingPath) break;
            }
            if (!foundAugmentingPath) break;
            int flow = Integer.MAX_VALUE;
            for (int v = sink; v != source; v = vv[parent[v] ^ 1]) {
                flow = Math.min(flow, cap[parent[v]]);
            }
            for (int v = sink; v != source; v = vv[parent[v] ^ 1]) {
                cap[parent[v]] -= flow;
                cap[parent[v] ^ 1] += flow;
            }
            total += flow;
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        T = sc.nextInt();
        for (int i = 0; i < n; i++) {
            s1[i] = sc.next();
        }
        for (int i = 0; i < n; i++) {
            s2[i] = sc.next();
        }

        Arrays.fill(head, -1);
        edge_idx = 0;
        for (int i = 0; i < 15; i++) {
            Arrays.fill(id[i], -1);
        }
        cnt = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (s1[i].charAt(j) == 'Z') {
                    xz = i; yz = j;
                } else if (check_inside(i, j)) {
                    id[i][j] = ++cnt;
                }
            }
        }
        source = 0;
        sink = 2 * cnt + 1;

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (check_inside(i, j)) {
                    for (int d = 0; d < 4; ++d) {
                        int x = i + directions[d][0];
                        int y = j + directions[d][1];
                        if (check_inside(x, y)) {
                            if (s2[x].charAt(y) != 0) {
                                add_edge(id[i][j] + cnt, sink, s2[x].charAt(y) - '0');
                            }
                            if (s1[i].charAt(j) == '0') continue;
                            add_edge(source, id[i][j], s1[i].charAt(j) - '0');
                            if (s2[x].charAt(y) != 0) {
                                add_edge(id[i][j], id[x][y] + cnt, 10);
                            }
                        }
                    }
                }
            }
        }
        System.out.println(run_max_flow());
        sc.close();
    }
}
